-- K.R.1.S TEST DATA — PART 1 OF 6. Run the parts in order.

BEGIN;
SET LOCAL search_path = kris;

-- ============================================================================
--  1. Remove earlier test data (children first where there is no cascade)
-- ============================================================================
DELETE FROM kris.communications WHERE customer_id LIKE 'TEST-%' OR vessel_id IN (SELECT id FROM kris.vessels WHERE is_test);
DELETE FROM kris.invoices WHERE customer_id LIKE 'TEST-%';
DELETE FROM kris.carbon_allocations WHERE vessel_id IN (SELECT id FROM kris.vessels WHERE is_test);
DELETE FROM kris.carbon_trades WHERE customer_id LIKE 'TEST-%';
DELETE FROM kris.geoform_reports WHERE imo IN (SELECT id FROM kris.vessels WHERE is_test);
DELETE FROM kris.veson_offhire WHERE imo IN (SELECT id FROM kris.vessels WHERE is_test);
DELETE FROM kris.vessels WHERE is_test;
DELETE FROM kris.fueleu_pools WHERE id LIKE 'TEST-%';
DELETE FROM kris.carbon_prices WHERE source LIKE 'TEST%';
DELETE FROM kris.companies WHERE id LIKE 'TEST-%';

-- ============================================================================
--  2. Companies — every party the vessels deal with (fictional, prefixed TEST)
--  roles: owner, manager, charterer, customer (who K.R.1.S reports to), counterparty
--  (carbon broker), verifier, supplier (bunkers). One company can have several roles.
-- ============================================================================
INSERT INTO kris.companies (id, name, roles, country_code, email_domain, is_test)
VALUES ('TEST-NWO', 'TEST Northwind Owners Ltd', ARRAY['owner']::text[], 'MH', 'northwind-owners.example', true),
('TEST-AOT', 'TEST Aurelia Tankers AS', ARRAY['owner']::text[], 'NO', 'aurelia-tankers.example', true),
('TEST-HLM', 'TEST Harbourline Ship Management Pte Ltd', ARRAY['manager', 'customer']::text[], 'SG', 'harbourline.example', true),
('TEST-MCH', 'TEST Meridian Chartering A/S', ARRAY['charterer']::text[], 'DK', 'meridian-chartering.example', true),
('TEST-ATE', 'TEST Atlas Energy Trading SA', ARRAY['charterer']::text[], 'CH', 'atlas-energy.example', true),
('TEST-ACB', 'TEST Alpine Carbon Brokers AG', ARRAY['counterparty']::text[], 'CH', 'alpine-carbon.example', true),
('TEST-NCM', 'TEST Nordic Carbon Markets AB', ARRAY['counterparty']::text[], 'SE', 'nordic-carbon.example', true),
('TEST-VER', 'TEST Verification Services BV', ARRAY['verifier']::text[], 'NL', 'verification.example', true),
('TEST-BRS', 'TEST Bunkers Rotterdam BV', ARRAY['supplier']::text[], 'NL', 'bunkers-rotterdam.example', true),
('TEST-GLS', 'TEST Gulf LNG Supply LLC', ARRAY['supplier']::text[], 'US', 'gulf-lng.example', true),
('TEST-SBS', 'TEST Santos Bunker Services Ltda', ARRAY['supplier']::text[], 'BR', 'santos-bunkers.example', true);

-- ============================================================================
--  3. Ports — real UN/LOCODEs, approximate positions
--  region decides regulation: EEA = EU MRV / EU ETS / FuelEU, UK = UK ETS, OTHER = neither.
--  in_eca = inside an emission control area (0.10% sulphur). latitude/longitude are the
--  berth a vessel alongside is shown at. Upserted, so a port that already exists is updated.
-- ============================================================================
INSERT INTO kris.ports (locode, name, country_code, country, region, in_eca, latitude, longitude)
VALUES ('BRSSZ', 'Santos', 'BR', 'Brazil', 'OTHER', false, -23.96, -46.3),
('NLRTM', 'Rotterdam', 'NL', 'Netherlands', 'EEA', true, 51.95, 4.14),
('PLGDN', 'Gdansk', 'PL', 'Poland', 'EEA', true, 54.4, 18.66),
('MACAS', 'Casablanca', 'MA', 'Morocco', 'OTHER', false, 33.61, -7.61),
('ZARCB', 'Richards Bay', 'ZA', 'South Africa', 'OTHER', false, -28.8, 32.08),
('GBIMM', 'Immingham', 'GB', 'United Kingdom', 'UK', true, 53.63, -0.19),
('GBTEE', 'Teesport', 'GB', 'United Kingdom', 'UK', true, 54.61, -1.16),
('USCRP', 'Corpus Christi', 'US', 'United States', 'OTHER', true, 27.81, -97.4),
('NOMON', 'Mongstad', 'NO', 'Norway', 'EEA', true, 60.81, 5.03),
('DEWVN', 'Wilhelmshaven', 'DE', 'Germany', 'EEA', true, 53.52, 8.15),
('CASJB', 'Saint John', 'CA', 'Canada', 'OTHER', true, 45.26, -66.06)
ON CONFLICT (locode) DO UPDATE SET name = EXCLUDED.name, country = EXCLUDED.country, region = EXCLUDED.region,
  in_eca = EXCLUDED.in_eca, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude;

-- ============================================================================
--  4. Vessels — id is the IMO number (every other table keys on it)
--  ship_type picks the CII reference line (kris.cii_ship_types); deadweight_t is the CII
--  capacity. department is what access control scopes on. is_test marks them as test rows.
-- ============================================================================
INSERT INTO kris.vessels (id, imo, name, department, vessel_code, ship_type, vessel_type, flag,
