-- ============================================================================
--  6. Voyages — one passage plus the stay at its destination
--  A voyage starts when the vessel leaves from_port and ends when it leaves to_port, which
--  is when the next one starts. laden legs carry cargo_qty_t (used for EEOI), ballast legs none.
--  voyage_ref (e.g. SNSTAR-2026-05) is how the rows below find their voyage.
-- ============================================================================
INSERT INTO kris.voyages (vessel_id, voyage_no, voyage_ref, from_port, to_port, departure_at, leg_type, cargo, cargo_qty_t, charterer_id)
SELECT d.vessel_id, d.voyage_no, d.voyage_ref, d.from_port, d.to_port, d.departure_at::timestamptz, d.leg_type, d.cargo, d.qty::numeric, d.charterer
  FROM (VALUES ('1000019', 'V2301', 'SNSTAR-2023-01', 'GBIMM', 'GBTEE', '2023-01-01T07:37:39.987Z', 'laden', 'Steam coal (remaining part cargo)', 24000, 'TEST-MCH'),
